/**
 * Ritorna le pagine che e' possibile utilizzare per URI pubblica o URI guest
 */
public Map<String, List<Layout>> getListaPagineUtilizzabili(long organizationId, long bandoId, long companyId)
		throws Exception {

	User defaultUser = userLocalService.getDefaultUser(companyId);
	Organization organization = organizationLocalService.getOrganization(organizationId);
	long groupId = organization.getGroup().getGroupId();

	Map<String, List<Layout>> pagineDivise = new HashMap<String, List<Layout>>();
	List<Layout> listaUriPrivata = new ArrayList<Layout>();
	List<Layout> listaUriPubblica = new ArrayList<Layout>();

	if (Validator.isNull(groupId)) {
		throw new NullPointerException("groupId e' null");
	}

	if (Validator.isNull(organizationId)) {
		throw new NullPointerException("organizationId e' null");
	}

	if (Validator.isNull(companyId)) {
		throw new NullPointerException("companyId e' null");
	}

	// ottengo la pagina parent
	Layout parentLayout = layoutLocalService.getLayoutByFriendlyURL(groupId, false,
			GestioneBandiFrontendPortletKeys.BANDI_FRIENDLY_URL);

	if (Validator.isNotNull(parentLayout)) {
		// ottengo tutte le pagine dei servizi
		List<Layout> listaPagine = layoutLocalService.getLayouts(groupId, false, parentLayout.getLayoutId());
		List<Layout> listaPagineFinita = null;
		if (Validator.isNotNull(listaPagine)) {
			List<Bando> listaBandi = bandoLocalService.getBandos(-1, -1);

			_log.debug("listaPagine" + listaPagine);

			listaPagineFinita = new ArrayList<Layout>(listaPagine);
			// rimuovo dalla lista servizi quelli gia' attivi per lo specifico ente
			for (Layout layout : listaPagine) {
				for (Bando bando : listaBandi) {
					if ((layout.getLayoutId() == bando.getLayoutId())
							|| (layout.getLayoutId() == bando.getLayoutId())) {
						if (bando.getBandoId() != bandoId) {
							_log.debug("layout rimosso" + layout.getLayoutId());
							listaPagineFinita.remove(layout);
						}
					}
				}
			}
		}

		for (Layout layout : listaPagineFinita) {
			boolean control = LayoutPermissionUtil.contains(PermissionCheckerFactoryUtil.create(defaultUser),
					layout, ActionKeys.VIEW);
			_log.debug("control: " + control);
			if (control) {
				listaUriPubblica.add(layout);
			} else {
				listaUriPrivata.add(layout);
			}
		}
	}
	pagineDivise.put(GestioneBandiFrontendPortletKeys.LISTA_URI_PRIVATE, listaUriPrivata);
	pagineDivise.put(GestioneBandiFrontendPortletKeys.LISTA_URI_PUBBLICHE, listaUriPubblica);

	return pagineDivise;

}

public boolean validaEspressione(String espressione) {
	boolean valida = calcoloAutomaticoService.validaEspressione(espressione);
	return valida;
}

public List<String> getPathFormula(String espressione){
	return calcoloAutomaticoService.getPathFormula(espressione);
